def get_contacts(
    db: Session, skip: int = 0, limit: int = 100
) -> List[contact_schemas.ContactResponse]:
    contacts = db.query(models.Contact).offset(skip).limit(limit).all()
    changed = False
    responses = []
    for contact in contacts:
        changed = _normalize_contact_structured_fields(contact) or changed
        responses.append(_contact_response_from_model(contact))
    if changed:
        db.commit()
    return responses

def search_contacts_by_name(db: Session, name_query: str) -> List[contact_schemas.ContactResponse]:
    contacts = (
        db.query(models.Contact).filter(
            models.Contact.name.ilike(f'%{name_query}%')
        ).all()
    )
    changed = False
    responses = []
    for contact in contacts:
        changed = _normalize_contact_structured_fields(contact) or changed
        responses.append(_contact_response_from_model(contact))
    if changed:
        db.commit()
    return responses
